import * as THREE from './vendor/three.module.js';
import {Forge,MATERIALS,TOOL_NAMES,clamp,ISLANDS} from './forge.js';
import {ForgeView} from './forge-view.js';
import {AudioSystem} from './audio.js';
const $=id=>document.getElementById(id),show=id=>$(id).classList.remove('hidden'),hide=id=>$(id).classList.add('hidden');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}};
const settings={volume:60,music:30,glow:85,sensitivity:65,...read('orbit-settings',{})};
const audio=new AudioSystem(settings),view=new ForgeView($('scene'),settings);
let forge=new Forge(),state=forge.s,active=false,paused=false,network=false,connected=false,ws=null,myId='local',hostId='',tool=0,material=0,shape=0,size=1,keys=new Set(),mouseDown=false,actionTimer=0,last=performance.now(),acc=0,netClock=0,uiClock=0,saved=null,saveClock=0,modal=false,roomAddress='',lastDiscovery=0;
const toolIcons=['◈','◎','✦','◉','⌁','⌫'];
const toolDesc=['좌클릭: 자유 물질 · 우클릭: 공간에 고정\nQ 재질 · B 모양 · 휠 크기','좌클릭: 인력 코어 · 우클릭: 척력 코어\n물질 8개 이상을 공전시켜 보세요.','빛의 씨앗을 놓으면 나선형 결정 정원이 자랍니다.','조준한 공간의 물질을 한꺼번에 흩뿌립니다.','물질 두 개를 차례로 클릭하면 탄성 연결됩니다.','조준한 물질·장치를 회수합니다.\nG 키는 고정·자유 상태 전환'];
const logLines=[];let toastTimer,achievementTimer;
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function log(text,kind=''){logLines.push({text,kind});if(logLines.length>45)logLines.shift();const root=$('console-log');root.replaceChildren();for(const item of logLines){const div=document.createElement('div');div.className='log-line '+item.kind;div.textContent=item.text;root.append(div);}root.scrollTop=root.scrollHeight;}
function chooseTool(i){tool=i;updateTools();audio.play('click');}
function updateTools(){const hot=$('hotbar');hot.replaceChildren();TOOL_NAMES.forEach((name,i)=>{const b=document.createElement('button');b.className=i===tool?'active':'';b.innerHTML=`<small>${i+1}</small><b>${toolIcons[i]}</b><span>${name}</span>`;b.onclick=()=>chooseTool(i);hot.append(b);});const pal=$('palette');pal.replaceChildren();MATERIALS.forEach((m,i)=>{const b=document.createElement('button');b.className=i===material?'active':'';b.style.background='#'+m.color.toString(16).padStart(6,'0');b.title=m.name;b.onclick=()=>{material=i;updateTools();};pal.append(b);});$('tool-name').textContent=TOOL_NAMES[tool];$('tool-description').textContent=toolDesc[tool];$('placement-mode').textContent=tool===0?`${MATERIALS[material].name} / ${['정육면체','광체 구','팔면 결정'][shape]} / ${size.toFixed(1)} m`:'자유 실험 도구';}
updateTools();
async function load(){if(window.desktop)saved=await window.desktop.loadWorld();else saved=read('orbit-world',null);}load();
async function save(){if(!active)return;try{const data=network?{...state,players:[],events:[]}:forge.save();if(!network){data.camera={x:view.camera.position.x,y:view.camera.position.y,z:view.camera.position.z,yaw:view.yaw,pitch:view.pitch};}if(network&&myId!==hostId){toast('협동 세계는 방장 PC에 저장됩니다.');return;}if(window.desktop)await window.desktop.saveWorld(data);else localStorage.setItem('orbit-world',JSON.stringify(data));saved=data;$('save-status').textContent='저장 완료 · '+new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});}catch(e){toast('저장하지 못했습니다: '+e.message);}}
function begin(savedWorld=null){network=false;forge=new Forge(savedWorld?.seed||Math.floor(Math.random()*1000000),savedWorld);forge.addPlayer('local',settings.name||'창조자');state=forge.s;myId='local';enter();if(savedWorld?.camera){const c=savedWorld.camera;view.camera.position.set(c.x,c.y,c.z);view.yaw=c.yaw||0;view.pitch=c.pitch||0;}log('공방에 도착했습니다. C는 실험실, /help는 공식 치트 목록입니다.','command');}
function enter(){active=true;paused=false;modal=false;view.lastEvent=0;view.yaw=0;view.pitch=-.12;view.camera.position.set(0,9,24);document.body.classList.add('in-game');hide('home');hide('lan-panel');show('hud');show('lock-hint');hide('pause');audio.init();audio.active=false;lastDiscovery=state.discoveries.length;updateTools();}
function lock(){if(!active)return;modal=false;paused=false;hide('pause');hide('lock-hint');$('scene').requestPointerLock();}
function unlock(){mouseDown=false;keys.clear();document.exitPointerLock?.();}
function openModal(id){modal=true;unlock();show(id);}
function closeModal(id){hide(id);modal=false;if(active&&!paused)show('lock-hint');if(id==='settings-panel'){localStorage.setItem('orbit-settings',JSON.stringify(settings));}}
function menu(){if(!active)return;modal=true;paused=true;unlock();show('pause');}
async function home(){await save();modal=true;unlock();if(ws){const socket=ws;ws=null;socket.close();}if(network)await window.desktop?.stopHost();network=false;connected=false;active=false;paused=false;modal=false;hide('hud');hide('pause');hide('console');show('home');document.body.classList.remove('in-game');forge=new Forge();state=forge.s;view.lastEvent=0;$('status').textContent='SANDBOX / OFFLINE';}
function send(m){if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify(m));}
function act(alternate=false,toggle=false){if(!active||paused||modal)return;const point=view.point(size);const data={type:'action',tool:toggle?5:tool,material,shape,size,...point,alternate,locked:tool===0&&alternate};if(network)send(data);else{const result=forge.action(myId,data);if(result.message)toast(result.message);}audio.play(tool===3?'pulse':tool===2?'heal':tool===1?'block':'shot');}
function command(text){if(!text.trim())return;log(text,'user');if(text.startsWith('/')){if(network)send({type:'command',text});else{const response=forge.command(myId,text);log(response,'command');toast(response.length<120?response:'명령 목록을 콘솔에서 확인하세요.');}}else if(network)send({type:'chat',text});else log(`${settings.name||'나'}: ${text}`);audio.play('click');}
function consoleOpen(prefix=''){modal=true;unlock();show('console');$('console-input').value=prefix;setTimeout(()=>$('console-input').focus(),30);}
function consoleClose(){hide('console');modal=false;$('console-input').blur();show('lock-hint');}
function showSettings(){for(const id of ['volume','music','glow','sensitivity']){$(id).value=settings[id];$(id+'-value').textContent=settings[id]+(id==='sensitivity'?'':'%');}openModal('settings-panel');}
for(const id of ['volume','music','glow','sensitivity'])$(id).oninput=()=>{settings[id]=Number($(id).value);$(id+'-value').textContent=settings[id]+(id==='sensitivity'?'':'%');audio.apply();localStorage.setItem('orbit-settings',JSON.stringify(settings));};
$('solo').onclick=()=>begin(saved);$('new').onclick=()=>{begin();toast('새 우주를 생성했습니다. 자동 저장이 이 세계로 갱신됩니다.');};$('guide').onclick=()=>openModal('guide-panel');$('settings').onclick=showSettings;$('pause-settings').onclick=showSettings;$('pause-button').onclick=menu;$('lock-hint').onclick=lock;$('resume').onclick=lock;$('back-home').onclick=home;$('save').onclick=()=>{save();toast('공방을 저장했습니다.');};
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>closeModal(b.dataset.close);
for(const b of document.querySelectorAll('[data-command]'))b.onclick=()=>command(b.dataset.command);
$('console-form').onsubmit=e=>{e.preventDefault();const text=$('console-input').value;command(text);$('console-input').value='';$('console-input').focus();};
$('lan').onclick=()=>{openModal('lan-panel');$('player-name').value=settings.name||'창조자';$('lan-error').textContent='';};
$('host').onclick=async()=>{if(!window.desktop){$('lan-error').textContent='데스크톱 실행 파일에서 방을 열 수 있습니다.';return;}$('host').disabled=true;settings.name=$('player-name').value||'창조자';try{const result=await window.desktop.host({saved,seed:saved?.seed||8241});if(!result.ok)throw new Error(result.error);roomAddress=result.addresses[0]||'127.0.0.1:3579';connect(result.url,result.token);}catch(e){$('lan-error').textContent=e.message;$('host').disabled=false;}};
$('join').onclick=()=>{let ip=$('ip').value.trim().replace(/^wss?:\/\//,'');if(!/^[a-zA-Z0-9.-]+(?::\d{1,5})?$/.test(ip)){$('lan-error').textContent='방장 주소를 입력하세요. 예: 192.168.0.12:3579';return;}if(!ip.includes(':'))ip+=':3579';roomAddress=ip;settings.name=$('player-name').value||'창조자';connect(`ws://${ip}/signal`);};
function connect(url,token){network=true;connected=false;$('lan-error').textContent='공방 신호를 찾는 중…';localStorage.setItem('orbit-settings',JSON.stringify(settings));const socket=new WebSocket(url);ws=socket;let error='',welcomed=false;const timeout=setTimeout(()=>{if(!welcomed){error='연결 시간이 초과되었습니다. 방장 IP와 네트워크를 확인하세요.';socket.close();}},7000);socket.onopen=()=>send({type:'hello',version:2,name:settings.name||'창조자',token});socket.onmessage=e=>{let m;try{m=JSON.parse(e.data);}catch{return;}if(m.type==='error'){error=m.message;$('lan-error').textContent=error;}if(m.type==='welcome'){clearTimeout(timeout);welcomed=true;connected=true;myId=m.id;hostId=m.hostId;state=m.state;enter();$('status').textContent='LAN / '+roomAddress;log('공방 연결 완료 · 주소 '+roomAddress,'command');toast('협동 공방에 연결했습니다. 주소: '+roomAddress);window.desktop?.copy(roomAddress);}if(m.type==='state'){state=m.state;hostId=m.hostId;}if(m.type==='notice'){log(m.message,'command');toast(m.message);}if(m.type==='chat')log(`${m.name}: ${m.text}`);};socket.onerror=()=>{error=error||'연결하지 못했습니다. 방장 IP·공유기·네트워크 접근을 확인하세요.';};socket.onclose=()=>{clearTimeout(timeout);$('host').disabled=false;if(ws!==socket)return;ws=null;connected=false;network=false;if(active){active=false;document.body.classList.remove('in-game');hide('hud');show('home');unlock();}openModal('lan-panel');$('lan-error').textContent=error||'공방 연결이 종료되었습니다.';};}
const full=()=>window.desktop?.fullscreen();$('full').onclick=full;$('settings-full').onclick=full;$('exit').onclick=async()=>{await save();window.desktop?.quit();};$('sound').onclick=()=>{audio.init();audio.muted=!audio.muted;audio.apply();toast(audio.muted?'사운드 OFF':'사운드 ON');};
document.addEventListener('pointerdown',()=>audio.init(),{once:true});document.addEventListener('pointerlockchange',()=>{const locked=document.pointerLockElement===$('scene');if(locked){hide('lock-hint');paused=false;modal=false;}else if(active&&!modal){menu();}});document.addEventListener('pointerlockerror',()=>{show('lock-hint');toast('화면을 다시 클릭해 시점 조작을 시작하세요.');});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement!==$('scene'))return;const sensitivity=settings.sensitivity/100*.003;view.yaw-=e.movementX*sensitivity;view.pitch=clamp(view.pitch-e.movementY*sensitivity,-1.52,1.52);});
document.addEventListener('mousedown',e=>{if(document.pointerLockElement!==$('scene')||modal)return;if(e.button===0){mouseDown=true;act(false);actionTimer=.16;}if(e.button===2)act(true);if(e.button===1&&view.target?.object.userData.nodeId){const n=state.nodes.find(n=>n.id===view.target.object.userData.nodeId);if(n){material=n.material||0;shape=n.shape||0;size=n.size;chooseTool(0);}}});document.addEventListener('mouseup',()=>mouseDown=false);document.addEventListener('contextmenu',e=>e.preventDefault());
document.addEventListener('wheel',e=>{if(document.pointerLockElement!==$('scene'))return;size=clamp(size+(e.deltaY<0?.2:-.2),.4,3);updateTools();},{passive:true});
document.addEventListener('keydown',e=>{if(e.code==='F11'){e.preventDefault();full();return;}if(e.code==='Escape'){if(!$('console').classList.contains('hidden')){consoleClose();return;}for(const id of ['cheats','guide-panel','settings-panel','lan-panel'])if(!$(id).classList.contains('hidden')){closeModal(id);return;}if(active&&paused){lock();return;}return;}if(document.activeElement?.tagName==='INPUT')return;if(!active)return;if(e.code==='KeyT'||e.code==='Slash'){e.preventDefault();consoleOpen(e.code==='Slash'?'/':'');return;}if(e.code==='KeyC'){openModal('cheats');return;}if(e.code==='KeyE'){openModal('guide-panel');return;}if(e.code==='KeyQ'){material=(material+1)%MATERIALS.length;updateTools();}if(e.code==='KeyB'){shape=(shape+1)%3;updateTools();}if(e.code==='KeyG'){act(true,true);}if(e.code==='KeyF')command('/fly');if(e.code==='Home')command('/home');if(e.code==='KeyZ'&&e.ctrlKey){e.preventDefault();command('/undo');}if(/^Digit[1-6]$/.test(e.code))chooseTool(Number(e.code.slice(-1))-1);if(['Space','Tab','ControlLeft','ControlRight'].includes(e.code))e.preventDefault();keys.add(e.code);});document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();mouseDown=false;if(active&&!network&&!modal)menu();});
function move(dt){if(!active||paused||modal||document.pointerLockElement!==$('scene'))return;const p=state.players.find(p=>p.id===myId);if(!p)return;const forward=new THREE.Vector3(-Math.sin(view.yaw),0,-Math.cos(view.yaw)),right=new THREE.Vector3(Math.cos(view.yaw),0,-Math.sin(view.yaw)),dir=new THREE.Vector3();if(keys.has('KeyW'))dir.add(forward);if(keys.has('KeyS'))dir.sub(forward);if(keys.has('KeyD'))dir.add(right);if(keys.has('KeyA'))dir.sub(right);if(keys.has('Space'))dir.y+=1;if(keys.has('ControlLeft')||keys.has('ControlRight'))dir.y-=1;if(dir.lengthSq())dir.normalize();const speed=p.speed*(keys.has('ShiftLeft')||keys.has('ShiftRight')?2.4:1);view.camera.position.addScaledVector(dir,speed*dt);if(!p.fly)view.camera.position.y-=dt*2;for(const is of ISLANDS)if((view.camera.position.x-is.x)**2+(view.camera.position.z-is.z)**2<is.r**2&&view.camera.position.y<is.y+1.7&&view.camera.position.y>is.y-2)view.camera.position.y=is.y+1.7;view.camera.position.x=clamp(view.camera.position.x,-180,180);view.camera.position.y=clamp(view.camera.position.y,-55,160);view.camera.position.z=clamp(view.camera.position.z,-180,180);if(view.camera.position.y<-50){command('/home');}if(!network){p.x=view.camera.position.x;p.y=view.camera.position.y;p.z=view.camera.position.z;p.yaw=view.yaw;p.pitch=view.pitch;p.tool=tool;p.material=material;}}
function hud(){if(!active)return;const p=view.camera.position;$('position').textContent=`${p.x.toFixed(0)} / ${p.y.toFixed(0)} / ${p.z.toFixed(0)}`;$('world-name').textContent=network?'우리의 궤도 공방':'나의 궤도 공방';$('world-stats').textContent=`${state.nodes.length} MATTER · ${state.gravity.toFixed(1)} G · ${state.orbitCount} ORBITING`;$('save-status').title=network?'방 주소: '+roomAddress:'';$('team').textContent=network?`LAN ${state.players.length}/4 · ${roomAddress} · ${state.players.filter(p=>p.id!==myId).map(p=>p.name).join(', ')}`:'자유 비행 · 공식 치트 활성';const n=state.nodes.find(n=>n.id===view.target?.object.userData.nodeId);$('target-name').textContent=n?(n.kind==='core'?(n.polarity<0?'척력':'인력')+' 중력 앵커':n.kind==='seed'?'결정 씨앗':MATERIALS[n.material]?.name||'결정')+(n.locked?' · 고정':' · 자유'):'';const tasks=[['matter','물질 12개 만들기'],['anchor','중력 앵커 놓기'],['seed','빛의 씨앗 심기'],['bond','물질 두 개 연결하기'],['orbit','물질 8개 공전시키기'],['build','청사진으로 건축하기']];const root=$('discovery-list');root.replaceChildren();for(const[id,title]of tasks){const d=document.createElement('div');d.className=state.discoveries.includes(id)?'done':'';d.textContent=(state.discoveries.includes(id)?'✓ ':'○ ')+title;root.append(d);}}
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;move(dt);if(active&&!network&&!paused){acc+=dt;while(acc>=1/60){forge.step(1/60);acc-=1/60;}state=forge.s;}else if(!active){forge.step(dt);state=forge.s;}if(active&&network&&connected){netClock+=dt;if(netClock>.08){const p=view.camera.position;send({type:'move',x:p.x,y:p.y,z:p.z,yaw:view.yaw,pitch:view.pitch,tool,material});netClock=0;}}if(active){actionTimer-=dt;if(mouseDown&&tool===0&&actionTimer<=0){act(false);actionTimer=.17;}view.events(state,myId,e=>{if(e.type==='teleport'&&e.player===myId)audio.play('dash');if(e.type==='discovery'){show('achievement');$('achievement').querySelector('b').textContent=e.title;clearTimeout(achievementTimer);achievementTimer=setTimeout(()=>hide('achievement'),4000);audio.play('level');}if(e.type==='grown')audio.play('heal');});uiClock+=dt;if(uiClock>.15){hud();uiClock=0;}saveClock+=dt;if(saveClock>20){save();saveClock=0;}}view.render(state,myId,dt,active);requestAnimationFrame(frame);}
requestAnimationFrame(frame);
window.orbitDiagnostics=()=>({active,network,connected,paused,nodes:state.nodes.length,bonds:state.bonds.length,discoveries:state.discoveries,players:state.players.length,position:view.camera.position.toArray(),renderer:view.renderer.info.render});
